		tgt.[apuk_regulatorycontactname] = stg.[apuk_regulatorycontactname],
		tgt.[apuk_regulatorycontactyominame] = stg.[apuk_regulatorycontactyominame],
		tgt.[apuk_requiredcompliancedate] = stg.[apuk_requiredcompliancedate],
